FuncDef.Code:
float opFiniteRepeatCenteredX(inout vec3 p, float spacing, int repetitions)
{
    // centering
    p.x += 0.5 * repetitions * spacing;

    float cellIndex = floor((p.x + spacing*0.5)/spacing);

    p.x = p.x - spacing * clamp(round(p.x / spacing), 0.0, repetitions);

    return cellIndex;
}
